CREATE DATABASE IF NOT EXISTS swiftlane; USE swiftlane;
DROP TABLE IF EXISTS rides; DROP TABLE IF EXISTS drivers; DROP TABLE IF EXISTS users;
CREATE TABLE users(id INT NOT NULL AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(20),role VARCHAR(20) NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE drivers(id INT NOT NULL AUTO_INCREMENT,user_id INT NOT NULL,vehicle_model VARCHAR(100) NOT NULL,vehicle_number VARCHAR(30) NOT NULL,rating DECIMAL(3,2) DEFAULT 4.50,available TINYINT(1) DEFAULT 1,PRIMARY KEY(id),UNIQUE KEY uq_vehicle(vehicle_number),CONSTRAINT fk_driver_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE rides(id INT NOT NULL AUTO_INCREMENT,customer_id INT NOT NULL,driver_id INT NULL,pickup VARCHAR(255) NOT NULL,destination VARCHAR(255) NOT NULL,cab_type VARCHAR(30) DEFAULT 'Mini',distance_km DECIMAL(8,2) DEFAULT 0,fare DECIMAL(10,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'requested',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_customer(customer_id),KEY idx_driver(driver_id),CONSTRAINT fk_ride_customer FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_ride_driver FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8;
